SELECT DISTINCTROW [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit, Montage.Membrantyp, Montage.[Element Nr], Montage.[Einschalt Datum], Montage.[Ausschalt Datum], [Gesamt Normierung].[I Gesamt], ([Gesamt Normierung]![I Gesamt]/GetGewFlaeche()) AS i, [Gesamt Normierung].Cc, [Gesamt Normierung].[t An], [Gesamt Normierung].[t Ka], ([Gesamt Normierung]![t An]+[Gesamt Normierung]![t Ka])/2 AS tm, [Gesamt Normierung].Uo, [Gesamt Normierung].Position, [Gesamt Normierung].Ui, Um.[Mittelwert von Ui], [Gesamt Normierung].Un, [tm]-([Mittelwert von Ui]-[Ui])*30 AS ti, Montage.Gruppe
FROM tblGewDaten, ([Gesamt Normierung] INNER JOIN Um ON ([Gesamt Normierung].Datum = Um.Datum) AND ([Gesamt Normierung].Elektrolyseur = Um.Elektrolyseur)) INNER JOIN Montage ON ([Gesamt Normierung].Position = Montage.Position) AND ([Gesamt Normierung].Elektrolyseur = Montage.Elektrolyseur)
WHERE ((([Gesamt Normierung].Datum)>=[Montage]![Einschalt Datum] And ([Gesamt Normierung].Datum)>=[tblGewDaten].[Anfangsdatum] And ([Gesamt Normierung].Datum)<=[tblGewDaten].[Enddatum]) AND ((Montage.[Ausschalt Datum]) Is Null) AND ((Montage.Gruppe)=(SELECT IDGruppe FROM tblGewDaten)))
ORDER BY [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit, [Gesamt Normierung].Position;
